#include <fstream>
#include <string>
#include <iostream>

int main() {
    std::fstream file;  // Creates a file stream object
    std::ios_base::openmode mode = std::ios_base::in | std::ios_base::out;  // Bitwise OR of flags
    file.open("example.txt", mode);  // Opens the file with specified mode
    if (file.is_open()) {
        std::cout << "File opened successfully." << std::endl;  // Check and proceed
        file.close();
    } else {
        std::cerr << "Failed to open file." << std::endl;
    }
    return 0;
}
